from .common import *

def rows(c):
 result=[]
 def add(code,msg,where,helper,source='engine_nodes n',order=None,node='n'):
  result.append(row(code,msg,source,where,node=node,order=order or f"printf('%020d/%06d/%024.6f',n.bfs,{helper*1000},0)"))
 decl="n.kind IN ('ClassDef','FunctionDef','AsyncFunctionDef')"
 for code,key,message,rank in [('BEI001','OLD_BOOTSTRAP_SYMBOLS',"'old bootstrap engine symbol '||n.name_repr||' must be deleted, not preserved'",0),('BEI002','DIRECT_BOOTSTRAP_NAMES',"'direct bootstrap/eager transition surface '||n.name_repr||' is forbidden'",0.1),('BEI047','DELETED_BOOTSTRAP_CALLBACK_SURFACES',"'deleted bootstrap callback/fallback surface '||n.name_repr||' must not be reintroduced'",0.2)]:
  add(code,message,decl+f' AND n.name IN {literals(c[key])}',rank)
 # Function metadata-publication parameters are independent of engine-file scope.
 add('BEI017',q('metadata publication must accept preplanned rows/plan, not rebuild inputs'),"f.kind='FunctionDef' AND f.name='publish_bootstrap_metadata_lazy' AND n.kind='arg' AND n.field='args' AND n.name IN ('bootstrap_plan','model_classes')",25,'function_nodes f JOIN a n ON n.__path=f.__path AND n.fn=f.id',order="printf('%020d/%06d/%024.6f',f.bfs,25000,n.position)")
 # Class-scoped lifecycle authority checks retain every nested use.
 lifecycle="EXISTS(SELECT 1 FROM a base WHERE base.__path=f.__path AND base.parent=f.id AND base.field='bases' AND base.kind IN ('Name','Attribute') AND base.name='PipelineLifecycleEffect')"
 classsrc='engine_nodes f JOIN a n ON n.__path=f.__path AND n.id BETWEEN f.id AND f.last'
 names=literals(c['BOOTSTRAP_LIFECYCLE_CONNECTION_NAMES'])
 for cond,msg in [(f"n.kind='arg' AND n.name IN {names}",'bootstrap lifecycle effects must not accept connection authority'),(f"n.kind='Name' AND n.name IN {names}",'bootstrap lifecycle effects must not use connection authority'),(f"n.kind='Attribute' AND n.name IN {literals(c['BOOTSTRAP_LIFECYCLE_CONNECTION_ATTRS'])}",'bootstrap lifecycle effects must not recover connection authority'),("n.kind='Call' AND EXISTS(SELECT 1 FROM calls call WHERE call.__path=n.__path AND call.id=n.id AND call.callee IN "+literals(c['BOOTSTRAP_LIFECYCLE_CONNECTION_CALLS'])+')','bootstrap lifecycle effects must not use dynamic connection dispatch or mutation')]:
  add('BEI032',q(msg),"f.kind='ClassDef' AND "+lifecycle+' AND '+cond,24,classsrc,order="printf('%020d/%06d/%024.6f',f.bfs,24000,n.bfs)")
 for code,key,message,rank in [('BEI002','DIRECT_BOOTSTRAP_NAMES',"'direct bootstrap/eager transition surface '||n.name_repr||' is forbidden'",30),('BEI047','DELETED_BOOTSTRAP_CALLBACK_SURFACES',"'deleted bootstrap callback/fallback surface '||n.name_repr||' must not be referenced'",30.1)]:
  add(code,message,f"n.kind IN ('Name','Attribute') AND n.name IN {literals(c[key])}",rank)
 add('BEI003',q('.resolve() is forbidden in bootstrap engine files'),"n.engine AND n.callee_kind='Attribute' AND n.callee='resolve' AND NOT EXISTS(SELECT 1 FROM functions f WHERE f.__path=n.__path AND f.id=n.fn AND f.name IN ('run','run_async'))",31,'engine_calls n')
 add('BEI004',q('lambda-backed bootstrap trampolines are forbidden; use named ServerPlan/IR steps'),"n.engine AND n.kind='Lambda' AND NOT EXISTS(SELECT 1 FROM a p WHERE p.__path=n.__path AND p.id=n.parent AND p.kind='keyword' AND p.name='default_factory')",32)
 # Engine-call helpers.
 empty_tuple="v.kind='Tuple' AND NOT "+child('v','elts',alias='element')
 add('BEI008',q('BootstrapApplicationPlan must contain real planned step refs, not a single-terminal skeleton'),"n.engine AND n.callee='BootstrapServerPlanContract' AND "+child('n','keywords',alias='kw',condition="kw.name='step_refs' AND "+child('kw','value',condition=empty_tuple))+" AND "+child('n','keywords',alias='kw',condition="kw.name='steps' AND "+child('kw','value',condition="v.kind='Tuple' AND (SELECT count(*) FROM a element WHERE element.__path=v.__path AND element.parent=v.id AND element.field='elts')<=1")),33,'engine_calls n')
 add('BEI009',q('lazy bootstrap index interrogation must use typed plan-owned facts, not a placeholder'),"n.engine AND n.callee='_bootstrap_engine_placeholder' AND "+child('n','args',condition="v.position=0 AND v.kind='Constant' AND v.value_kind='str' AND v.value='lazy bootstrap index interrogation'"),34,'engine_calls n')
 add('BEI010',q('lazy coordinator must derive desired physical contracts without passing a runtime connection'),"n.engine AND n.basename='bootstrap_coordinator.py' AND n.callee='_plan_physical_schema_contract' AND "+child('n','keywords',condition="v.name='conn'"),35,'engine_calls n')
 publication="n.engine AND n.callee='publish_bootstrap_metadata_lazy'"
 add('BEI017',q('metadata publication must not receive positional fallback reconstruction inputs'),publication+' AND '+child('n','args'),36,'engine_calls n')
 missing="(SELECT '['||group_concat(quote(name),', ')||']' FROM (SELECT 'publication_plan' name UNION ALL SELECT 'publication_rows') required WHERE NOT EXISTS(SELECT 1 FROM a k WHERE k.__path=n.__path AND k.parent=n.id AND k.field='keywords' AND k.name=required.name))"
 add('BEI017',"'metadata publication call must pass preplanned artifacts: '||"+missing,publication+' AND '+missing+' IS NOT NULL',36.1,'engine_calls n')
 add('BEI017',q('metadata publication artifacts must come from BootstrapApplicationPlan'),publication+" AND n.basename='bootstrap_coordinator.py' AND EXISTS(SELECT 1 FROM functions f WHERE f.__path=n.__path AND f.id=n.fn AND f.name='_enqueue_application_schema_lazy') AND k.name IN ('publication_plan','publication_rows') AND NOT (v.kind='Attribute' AND "+child('v','value',alias='obj',condition="obj.kind='Name' AND obj.name='application_plan'")+')',36.2,'engine_calls n JOIN a k ON k.__path=n.__path AND k.parent=n.id AND k.field=\'keywords\' JOIN a v ON v.__path=k.__path AND v.parent=k.id AND v.field=\'value\'',node='v',order="printf('%020d/%06d/%024.6f',n.bfs,36200.0,k.position)")
 add('BEI020',q('bootstrap SQL assertions must fail closed when a planned source ref is missing'),"n.engine AND n.basename='bootstrap_coordinator.py' AND n.callee_kind='Attribute' AND n.callee='get' AND n.receiver_kind='Name' AND n.receiver_name='table_source_refs' AND (SELECT count(*) FROM a arg WHERE arg.__path=n.__path AND arg.parent=n.id AND arg.field='args')>1 AND EXISTS(SELECT 1 FROM functions f WHERE f.__path=n.__path AND f.id=n.fn AND f.name='_application_sql_assertions_for_plan')",37,'engine_calls n')
 # The source calls the synthetic assertion helper only for Call nodes. Its Name
 # branch is unreachable and must not become an invented rule.
 add('BEI018',"CASE WHEN n.name='BootstrapObservedState' THEN 'schema generation planning must consume BootstrapObservation facts only' ELSE 'schema generation planning must not read legacy generation maps' END","f.kind='FunctionDef' AND f.name='plan_bootstrap_schema_generation' AND n.kind='Name' AND n.name IN ('BootstrapObservedState','SCHEMA_GENERATION_GLOBAL_TAG')",50,'function_nodes f JOIN a n ON n.__path=f.__path AND n.id BETWEEN f.id AND f.last',order="printf('%020d/%06d/%024.6f',f.bfs,50000,n.bfs)")
 add('BEI018',q("schema generation/version counters must be explicit, not inferred with 'or'"),"p.kind='BoolOp' AND p.op='Or' AND n.kind='Attribute' AND n.field='values' AND n.name IN ('schema_generation','schema_version')",50,'engine_nodes p JOIN a n ON n.__path=p.__path AND n.parent=p.id',order="printf('%020d/%06d/%024.6f',p.bfs,50000,n.position)")
 helper="substr(n.__path,1,37)='data_layer_testing/helpers/bootstrap' AND instr(substr(n.__path,28),'/')=0"
 # Compare the complete relative parent, not a loose substring of an arbitrary path.
 helper="rx_matches(n.__path,'^data_layer_testing/helpers/bootstrap[^/]*$')"
 add('BEI021',q('test bootstrap helpers must use the lazy bootstrap coordinator path, not probe or mutate proof caches'),helper+f' AND n.callee IN {literals(c["HELPER_BOOTSTRAP_PROBE_NAMES"])}',51,'engine_calls n')
 add('BEI021',q('test bootstrap helpers must not maintain helper-owned bootstrap proof state'),helper+f" AND n.kind IN ('Name','Attribute') AND n.name IN {literals(c['HELPER_BOOTSTRAP_PROOF_ATTRS'])}",51)
 add('BEI028',q('backend-specific bootstrap probes must live behind explicit interrogation/replay collaborators'),f"n.basename!='bootstrap_backend_collaborators.py' AND (substr(n.basename,1,9)='bootstrap' OR instr('/'||n.__path||'/','/bootstrap/')>0) AND n.kind='Attribute' AND n.name IN {literals(c['BACKEND_PROBE_ATTRS'])}",52)
 add('BEI041',"'schema reconciliation planning must consume SchemaStateSnapshot facts, not call physical/introspection fallback '||(SELECT name_repr FROM a x WHERE x.__path=n.__path AND x.id=n.callee_id)",f"(instr('/'||n.__path||'/','/l2200_sql_dialect/')>0 OR n.basename='generic_sparse.py') AND n.callee IN {literals(c['RECONCILIATION_PLANNING_PROBE_CALLS'])}",53,'engine_calls n')
 add('BEI035',"'deleted schema sidecar pending deferred-state field '||n.name_repr||' must not be reintroduced'","instr('/'||n.__path||'/','/l2200_sql_dialect/')>0 AND n.kind='Attribute' AND substr(n.name,1,8)='pending_' AND "+child('n','value',condition="v.kind='Name' AND v.name='deferred_state'"),54)
 add('BEI042',"'bootstrap application must not use deleted lazy-result scaffolding '||n.name_repr||'; return the fused terminal LazyResult directly'",f"n.basename IN ('bootstrap_application_plan.py','bootstrap_coordinator.py') AND n.kind IN ('Name','Attribute') AND n.name IN {literals(c['DELETED_APPLICATION_PLAN_SCAFFOLDING'])}",55)
 manifest=f"n.basename='bootstrap_interrogation.py' AND n.kind IN ('FunctionDef','AsyncFunctionDef') AND n.name IN {literals(c['INTERROGATION_MANIFEST_SYNTHESIS_NAMES'])}"
 for rank in [26,56]:add('BEI022',q('interrogation decoding must consume explicit proof/seed rows, not synthesize facts from manifest payloads'),manifest,rank)
 add('BEI022',q('interrogation facts must not fall back to request defaults or manifest-derived hashes'),"n.basename='bootstrap_interrogation.py' AND n.kind='BoolOp' AND n.op='Or' AND "+child('n','values',condition="v.kind IN ('Name','Attribute') AND v.name IN ('request','proof_hashes','seed_hashes')"),56)
 return result
